def components(grid, color=2):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==color and (i,j) not in seen:
                stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==color and (nr,nc) not in seen:
                                seen.add((nr,nc)); stack.append((nr,nc))
                comps.append(cells)
    return comps

def f(grid):
    g=[r[:] for r in grid]
    comps=components(g)
    info=[(sum(r for r,_ in ce)/len(ce), sum(c for _,c in ce)/len(ce), ce) for ce in comps]
    for a in range(len(info)):
        for b in range(a+1,len(info)):
            ra,ca,ea=info[a]; rb,cb,eb=info[b]
            if ra==rb and abs(ra-round(ra))<1e-9:
                r=int(round(ra)); lo=max(c for _,c in ea); hi=min(c for _,c in eb)
                if lo>hi: lo,hi=hi,lo
                for c in range(lo+1,hi): g[r][c]=1
